import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.CslsFoWx.js";const i="/VendoraSystem-docs/captures/2026-11-06-44-white-label/01-web-apparence-apercus-caisse-kiosque-ticket.jpg",o="/VendoraSystem-docs/captures/2026-11-06-44-white-label/02-web-config-appareil-layout-assigne.jpg",n="/VendoraSystem-docs/captures/2026-11-06-44-white-label/03-web-ticket-zones-branding-apercu-80mm.jpg",c="/VendoraSystem-docs/captures/2026-11-06-44-white-label/04-web-ticket-reseaux-sociaux-qr.jpg",l="/VendoraSystem-docs/captures/2026-11-06-44-white-label/05-web-apparence-apercu-ticket-80mm.jpg",d="/VendoraSystem-docs/captures/2026-11-06-44-white-label/06-web-editeur-layout-versions-conservees.jpg",u="/VendoraSystem-docs/captures/2026-11-06-44-white-label/07-web-editeur-layout-confirmation-restauration.jpg",p="/VendoraSystem-docs/captures/2026-11-06-44-white-label/08-web-editeur-layout-version-restauree.jpg",g="/VendoraSystem-docs/captures/2026-11-06-44-white-label/09-web-kiosque-images-accueil-banniere.jpg",_=JSON.parse('{"title":"Lot 4.4 — White-label complet : layout par appareil, zones du ticket, images kiosque, restauration des layouts (06/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-06-44-white-label.md","filePath":"generated/preuves/2026-11-06-44-white-label.md","lastUpdated":null}'),m={name:"preuves/2026-11-06-44-white-label.md"};function b(f,e,h,w,y,k){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="lot-4-4-—-white-label-complet-layout-par-appareil-zones-du-ticket-images-kiosque-restauration-des-layouts-06-11-2026" tabindex="-1">Lot 4.4 — White-label complet : layout par appareil, zones du ticket, images kiosque, restauration des layouts (06/11/2026) <a class="header-anchor" href="#lot-4-4-—-white-label-complet-layout-par-appareil-zones-du-ticket-images-kiosque-restauration-des-layouts-06-11-2026" aria-label="Permalink to &quot;Lot 4.4 — White-label complet : layout par appareil, zones du ticket, images kiosque, restauration des layouts (06/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-06-44-white-label</code> · 9 image(s) · 0 trace(s)</p><div><p>Preuves sur la vraie stack : serveur Spring Boot local (8080, migration V74 appliquée), back-office Angular (<code>ng serve</code> 4200), commerce de démonstration en euros « Épicerie fine Dupont — Lyon » (<code>epicerie.demo-315@exemple.tn</code>, valeurs fictives : adresse, téléphone, réseaux). Viewport 1280 × 900, thème clair. Données créées par l&#39;API : second layout de vente « Rayon frais — été », zones de branding du ticket, images de bannière et d&#39;écran d&#39;accueil (PNG générés).</p><table tabindex="0"><thead><tr><th>Fichier</th><th>Ce qu&#39;on voit</th></tr></thead><tbody><tr><td><code>01-web-apparence-apercus-caisse-kiosque-ticket.jpg</code></td><td><strong>Apparence › Thème</strong> : à côté de l&#39;aperçu caisse existant, les deux nouveaux aperçus rendus avec le thème en cours d&#39;édition — <strong>kiosque</strong> (fond primaire, nom, « Touchez pour commander », bandeau bannière secondaire) et <strong>ticket 80 mm</strong>.</td></tr><tr><td><code>02-web-config-appareil-layout-assigne.jpg</code></td><td><strong>Configuration par appareil</strong> : nouvelle colonne <strong>Layout de vente</strong> (« Défaut du magasin » ou un layout du magasin compatible avec le rôle) ; « Rayon frais — été » assigné à la caisse de démo, « configuration publiée (version 2) » → <code>DeviceConfigUpdated</code> avec <code>salesLayoutId</code> vers cet appareil.</td></tr><tr><td><code>03-web-ticket-zones-branding-apercu-80mm.jpg</code></td><td><strong>Ticket et balance › Zones de branding (spec 13)</strong> : logo en en-tête (o/n), message d&#39;accueil (48/200), mentions légales (51/200) ; à droite, l&#39;<strong>aperçu 80 mm</strong> en direct : identité, « Bienvenue chez Dupont, épicerie fine depuis 1987 », lignes fictives, TOTAL, « Votre reçu en ligne » + QR, pied (message, mentions, Instagram, Site).</td></tr><tr><td><code>04-web-ticket-reseaux-sociaux-qr.jpg</code></td><td>Suite de la section : <strong>Réseaux sociaux (2/3)</strong> (Instagram <code>@epicerie_dupont</code>, Site web <code>epicerie-dupont.fr</code>, Retirer, Ajouter un réseau), case <strong>QR du reçu en ligne sur le ticket</strong>, puis le bloc « Étiquettes de balance » inchangé.</td></tr><tr><td><code>05-web-apparence-apercu-ticket-80mm.jpg</code></td><td>Aperçu ticket de la page Apparence avec le pied du profil ticket (message, mentions, réseaux) et le QR du reçu en ligne.</td></tr><tr><td><code>06-web-editeur-layout-versions-conservees.jpg</code></td><td><strong>Écran de vente</strong> (layout « Rayon frais — été », version 2) : bouton <strong>Restaurer la version précédente</strong> et liste « Versions conservées : v1 — 1 page(s), 18 bouton(s) ».</td></tr><tr><td><code>07-web-editeur-layout-confirmation-restauration.jpg</code></td><td>Dialogue du kit : « Le layout « Rayon frais — été » reprendra le contenu de la version 1 et sera publié aux caisses. Les modifications non publiées seront perdues. »</td></tr><tr><td><code>08-web-editeur-layout-version-restauree.jpg</code></td><td>Après confirmation : <strong>Version 3</strong>, bandeau « Version précédente restaurée (publiée en version 3) — les caisses l&#39;appliquent à la prochaine synchronisation », versions conservées <strong>v2</strong> et <strong>v1</strong> (on peut revenir en arrière puis en avant).</td></tr><tr><td><code>09-web-kiosque-images-accueil-banniere.jpg</code></td><td><strong>Apparence › Kiosque › preset « Borne entrée »</strong> : <strong>Image d&#39;accueil</strong> (vignette, Téléverser une image, Retirer l&#39;image, « mise en cache sur chaque kiosque ») et <strong>Bannières (1/5)</strong> « Promo du jour : fromages » avec sa vignette ; images téléversées par <code>POST /stores/{id}/kiosk-assets</code> et référencées par le preset.</td></tr></tbody></table><h2 id="caisses-android-ios" tabindex="-1">Caisses (Android, iOS) <a class="header-anchor" href="#caisses-android-ios" aria-label="Permalink to &quot;Caisses (Android, iOS)&quot;">​</a></h2><p>Pas de capture d&#39;appareil pour ce lot : l&#39;assignation d&#39;un layout et le profil ticket du magasin des caisses de démonstration (TND) exigent le rôle OWNER / ADMIN, que les comptes de démonstration disponibles n&#39;ont pas. Les deux caisses sont prouvées par leurs tests unitaires, exécutés dans la suite complète :</p><ul><li><strong>Android</strong> (<code>CatalogViewModelDeviceLayout44Test</code>, <code>WhiteLabel44TicketTest</code>) : layout assigné utilisé, repli sur le défaut quand il a disparu ou est réservé au rôle KIOSK, <code>DeviceConfigUpdated</code> au pull → boutons rechargés ; ticket de vente avec accueil, mentions légales, deux réseaux et QR désactivé (lignes « Instagram : @epicerie_omar », aucun QR, pas de <code>GS ( k</code> dans les octets), <code>headerShowLogo = false</code> → aucune image, nom en double taille.</li><li><strong>iOS</strong> (<code>WhiteLabel44Tests</code>) : mêmes scénarios, plus le vrai chemin <code>CheckoutViewModel → PrintingViewModel → transport factice</code> dont le dump imprimé porte les réseaux sans <code>[LOGO]</code> ni « Votre reçu en ligne ».</li></ul><p>Serveur : <code>WhiteLabel44IntegrationTest</code> (layout par appareil 422/OK/retrait, historique et restauration 409 → v3, images kiosque réduites à 1 024 px et lisibles par un appareil, zones du ticket normalisées et diffusées, 422 au-delà de 200 caractères). Partagé : <code>WhiteLabel44Test</code>.</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/01-web-apparence-apercus-caisse-kiosque-ticket.jpg" target="_blank"><img src="'+i+'" alt="01-web-apparence-apercus-caisse-kiosque-ticket.jpg" loading="lazy"></a><figcaption>01-web-apparence-apercus-caisse-kiosque-ticket.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/02-web-config-appareil-layout-assigne.jpg" target="_blank"><img src="'+o+'" alt="02-web-config-appareil-layout-assigne.jpg" loading="lazy"></a><figcaption>02-web-config-appareil-layout-assigne.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/03-web-ticket-zones-branding-apercu-80mm.jpg" target="_blank"><img src="'+n+'" alt="03-web-ticket-zones-branding-apercu-80mm.jpg" loading="lazy"></a><figcaption>03-web-ticket-zones-branding-apercu-80mm.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/04-web-ticket-reseaux-sociaux-qr.jpg" target="_blank"><img src="'+c+'" alt="04-web-ticket-reseaux-sociaux-qr.jpg" loading="lazy"></a><figcaption>04-web-ticket-reseaux-sociaux-qr.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/05-web-apparence-apercu-ticket-80mm.jpg" target="_blank"><img src="'+l+'" alt="05-web-apparence-apercu-ticket-80mm.jpg" loading="lazy"></a><figcaption>05-web-apparence-apercu-ticket-80mm.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/06-web-editeur-layout-versions-conservees.jpg" target="_blank"><img src="'+d+'" alt="06-web-editeur-layout-versions-conservees.jpg" loading="lazy"></a><figcaption>06-web-editeur-layout-versions-conservees.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/07-web-editeur-layout-confirmation-restauration.jpg" target="_blank"><img src="'+u+'" alt="07-web-editeur-layout-confirmation-restauration.jpg" loading="lazy"></a><figcaption>07-web-editeur-layout-confirmation-restauration.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/08-web-editeur-layout-version-restauree.jpg" target="_blank"><img src="'+p+'" alt="08-web-editeur-layout-version-restauree.jpg" loading="lazy"></a><figcaption>08-web-editeur-layout-version-restauree.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-06-44-white-label/09-web-kiosque-images-accueil-banniere.jpg" target="_blank"><img src="'+g+'" alt="09-web-kiosque-images-accueil-banniere.jpg" loading="lazy"></a><figcaption>09-web-kiosque-images-accueil-banniere.jpg</figcaption></figure></div>',5)])])}const j=a(m,[["render",b]]);export{_ as __pageData,j as default};
